fn main() -> Int {
  let has_ticket = true;
  let is_vip = false;
  if has_ticket {
    io.println("Ticket checked.");
    if is_vip {
      io.println("VIP entrance!");
    } else {
      io.println("General entrance.");
    }
  }
  return 0;
}
